CREATE TABLE bangkok_attractions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    city TEXT NOT NULL,
    attraction TEXT NOT NULL,
    cost_usd REAL,
    child_price_usd REAL,
    age_of_child INTEGER,
    child_price_note TEXT,
    public_transport TEXT,
    dates_closed TEXT,
    days_of_week_closed TEXT
);

